import { useState } from "react";

function App() {
  const [text, setText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleExtract = async () => {
    if (!text) return;

    setLoading(true);

    try {
      const response = await fetch("http://127.0.0.1:8000/extract", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          job_description: text,
        }),
      });

      const data = await response.json();
      setResult(data);
    } catch (error) {
      console.error(error);
    }

    setLoading(false);
  };

  const isLimited = result?.skills?.includes("LIMIT REACHED");

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h1 style={styles.title}>Job Skills Extractor</h1>

        <textarea
          style={styles.textarea}
          placeholder="Paste job description here..."
          value={text}
          onChange={(e) => setText(e.target.value)}
        />

        <button style={styles.button} onClick={handleExtract}>
          {loading ? "Extracting..." : "Extract Skills"}
        </button>

        {result && (
          <div style={styles.results}>
            <Section title="Core Skills" data={result.core_skills} />

            <Section title="All Skills" data={result.skills} />

            <h3>Missing Skills</h3>
            {isLimited ? (
              <div style={styles.locked}>
                🔒 Upgrade to unlock
                <button
                  style={styles.upgradeBtn}
                  onClick={() =>
                    window.open("https://your-payment-link.com", "_blank")
                  }
                >
                  Upgrade
                </button>
              </div>
            ) : (
              <ul>
                {(result.missing_skills || []).map((s, i) => (
                  <li key={i}>{s}</li>
                ))}
              </ul>
            )}

            <h3>Level</h3>
            <p>{result.level}</p>
          </div>
        )}
      </div>
    </div>
  );
}

function Section({ title, data }) {
  return (
    <>
      <h3>{title}</h3>
      <ul>
        {(data || []).map((item, index) => (
          <li key={index}>{item}</li>
        ))}
      </ul>
    </>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    background: "#0f172a",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    color: "white",
  },
  card: {
    background: "#1e293b",
    padding: "30px",
    borderRadius: "12px",
    width: "600px",
    boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
  },
  title: {
    marginBottom: "20px",
  },
  textarea: {
    width: "100%",
    height: "150px",
    padding: "10px",
    borderRadius: "8px",
    border: "none",
    marginBottom: "15px",
  },
  button: {
    width: "100%",
    padding: "12px",
    background: "#6366f1",
    color: "white",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    marginBottom: "20px",
  },
  results: {
    marginTop: "20px",
  },
  locked: {
    background: "#334155",
    padding: "15px",
    borderRadius: "8px",
    textAlign: "center",
  },
  upgradeBtn: {
    marginTop: "10px",
    padding: "10px 15px",
    background: "#22c55e",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    color: "white",
  },
};

export default App;
